begin;
create table if not exists public.be_data_entry_service_providers (
 provider_code text primary key, display_name text not null, provider_type text not null default 'OUTSOURCE', is_active boolean not null default true, updated_at timestamptz not null default now());
alter table public.be_data_entry_service_providers enable row level security;
drop policy if exists be_data_entry_service_providers_read_auth on public.be_data_entry_service_providers;
create policy be_data_entry_service_providers_read_auth on public.be_data_entry_service_providers for select to authenticated using (is_active);
revoke all on public.be_data_entry_service_providers from public, anon;
grant select on public.be_data_entry_service_providers to authenticated;
on conflict(provider_code) do update set display_name=excluded.display_name,provider_type=excluded.provider_type,is_active=true,updated_at=now();
create table if not exists public.be_data_entry_tariff_catalog (
 destination_key text primary key, destination_name text not null, original_label text, standard_rate_mmk numeric not null check(standard_rate_mmk>=0), special_rate_mmk numeric check(special_rate_mmk>=0), rack_code text, provider_code text not null references public.be_data_entry_service_providers(provider_code), is_active boolean not null default true, source_file text not null default 'updated_tariff.csv', updated_at timestamptz not null default now());
alter table public.be_data_entry_tariff_catalog enable row level security;
drop policy if exists be_data_entry_tariff_catalog_read_auth on public.be_data_entry_tariff_catalog;
create policy be_data_entry_tariff_catalog_read_auth on public.be_data_entry_tariff_catalog for select to authenticated using (is_active);
revoke all on public.be_data_entry_tariff_catalog from public, anon;
grant select on public.be_data_entry_tariff_catalog to authenticated;


create or replace function public.be_data_entry_tariff_options()
returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(jsonb_agg(jsonb_build_object('destination_key',c.destination_key,'destination_name',c.destination_name,'standard_rate_mmk',c.standard_rate_mmk,'special_rate_mmk',c.special_rate_mmk,'rack_code',c.rack_code,'provider_code',c.provider_code,'provider_name',p.display_name) order by c.destination_name),'[]'::jsonb)
 from public.be_data_entry_tariff_catalog c join public.be_data_entry_service_providers p using(provider_code) where c.is_active and p.is_active and auth.uid() is not null;
$$;
revoke all on function public.be_data_entry_tariff_options() from public,anon;
grant execute on function public.be_data_entry_tariff_options() to authenticated;
commit;

;
